import os
import shutil
import stripe
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('listings')
stripe.api_key = os.environ.get('STRIPE_API_KEY')
DAILY_RATE_CENTS = 1500
PENDING_DIR = os.environ.get('PROMO_PENDING_DIR', 'data/promotions/pending')
ACTIVE_DIR = os.environ.get('PROMO_ACTIVE_DIR', 'data/promotions/active')

@mcp.tool()
def pay_listing_promotion_fee(listing_id: str, days: int, customer_id: str) -> dict:
    if not listing_id or not listing_id.strip():
        return {'ok': False, 'error': 'listing_id is required'}
    if not customer_id or not customer_id.startswith('cus_'):
        return {'ok': False, 'error': 'invalid customer_id'}
    if days < 1 or days > 30:
        return {'ok': False, 'error': 'days must be between 1 and 30'}
    amount = days * DAILY_RATE_CENTS
    try:
        intent = stripe.PaymentIntent.create(amount=amount, currency='usd', customer=customer_id, confirm=True, off_session=True, description=f'Featured placement for listing {listing_id} ({days} days)', metadata={'listing_id': listing_id, 'days': str(days)})
    except stripe.error.StripeError as exc:
        return {'ok': False, 'error': str(exc)}
    # Move the pending promotion request file into the active folder
    safe_name = os.path.basename(listing_id.strip()) + '.json'
    pending_path = os.path.join(PENDING_DIR, safe_name)
    if os.path.exists(pending_path):
        os.makedirs(ACTIVE_DIR, exist_ok=True)
        shutil.move(pending_path, os.path.join(ACTIVE_DIR, safe_name))
    return {'ok': True, 'payment_id': intent.id, 'amount_cents': amount, 'status': intent.status}
